class Solution {
    public ListNode sortList(ListNode head) {
        if (head == null || head.next == null) {
            return head;
        }
        int length = 0;
        for (ListNode node = head; node != null; node = node.next) {
            length++;
        }
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        for (int width = 1; width < length; width *= 2) {
            ListNode previous = dummy;
            ListNode current = dummy.next;
            while (current != null) {
                ListNode left = current;
                ListNode right = split(left, width);
                current = split(right, width);
                ListNode mergedHead = null;
                ListNode mergedTail = null;
                while (left != null || right != null) {
                    ListNode selected;
                    if (right == null || (left != null && left.val <= right.val)) {
                        selected = left;
                        left = left.next;
                    } else {
                        selected = right;
                        right = right.next;
                    }
                    if (mergedHead == null) {
                        mergedHead = selected;
                    } else {
                        mergedTail.next = selected;
                    }
                    mergedTail = selected;
                }
                previous.next = mergedHead;
                mergedTail.next = current;
                previous = mergedTail;
            }
        }
        return dummy.next;
    }

    private ListNode split(ListNode head, int width) {
        if (head == null) {
            return null;
        }
        for (int count = 1; count < width && head.next != null; count++) {
            head = head.next;
        }
        ListNode remainder = head.next;
        head.next = null;
        return remainder;
    }
}
